        q("phy-heat-quantity-002","phy-heat-quantity","How much energy raises 0.5 kg of water by 10 K if c = 4200 J kg⁻¹ K⁻¹?",listOf("210 J","2100 J","21 000 J","210 000 J"),2,"Q = mcΔT = 0.5 × 4200 × 10 = 21 000 J."),
